CREATE DATABASE IF NOT EXISTS domain_hub CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE domain_hub;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('USER','ADMIN') NOT NULL DEFAULT 'USER',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE tlds(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,extension VARCHAR(20) NOT NULL UNIQUE,registration_price DECIMAL(10,2) NOT NULL CHECK(registration_price>=0),renewal_price DECIMAL(10,2) NOT NULL CHECK(renewal_price>=0),active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE domains(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(63) NOT NULL,extension VARCHAR(20) NOT NULL,owner_id BIGINT UNSIGNED NOT NULL,expires_at DATE NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_domain(name,extension),FOREIGN KEY(extension) REFERENCES tlds(extension),FOREIGN KEY(owner_id) REFERENCES users(id),INDEX idx_domains_owner(owner_id),INDEX idx_domains_expiry(expires_at)) ENGINE=InnoDB;
CREATE TABLE orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,domain_id BIGINT UNSIGNED NULL,order_type ENUM('REGISTRATION','RENEWAL','TRANSFER_PURCHASE') NOT NULL,amount DECIMAL(10,2) NOT NULL,status ENUM('COMPLETED','FAILED') NOT NULL,request_key VARCHAR(100) UNIQUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(domain_id) REFERENCES domains(id),INDEX idx_orders_user(user_id,created_at)) ENGINE=InnoDB;
CREATE TABLE payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL UNIQUE,amount DECIMAL(10,2) NOT NULL,status ENUM('SUCCESS','FAILED') NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id),INDEX idx_pay_status(status)) ENGINE=InnoDB;
CREATE TABLE dns_records(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,domain_id BIGINT UNSIGNED NOT NULL,record_type ENUM('A','AAAA','CNAME','MX','TXT','NS') NOT NULL,name VARCHAR(253) NOT NULL,value VARCHAR(1000) NOT NULL,priority INT NULL,ttl INT NOT NULL DEFAULT 3600,FOREIGN KEY(domain_id) REFERENCES domains(id) ON DELETE CASCADE,INDEX idx_dns_domain(domain_id)) ENGINE=InnoDB;
CREATE TABLE transfers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,domain_id BIGINT UNSIGNED NOT NULL,sender_id BIGINT UNSIGNED NOT NULL,receiver_id BIGINT UNSIGNED NOT NULL,status ENUM('PENDING','ACCEPTED','REJECTED') NOT NULL DEFAULT 'PENDING',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(domain_id) REFERENCES domains(id),FOREIGN KEY(sender_id) REFERENCES users(id),FOREIGN KEY(receiver_id) REFERENCES users(id),INDEX idx_transfer_party(sender_id,receiver_id,status),INDEX idx_transfer_receiver(receiver_id,status)) ENGINE=InnoDB;
CREATE TABLE auctions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,domain_id BIGINT UNSIGNED NOT NULL,seller_id BIGINT UNSIGNED NOT NULL,starting_price DECIMAL(10,2) NOT NULL,min_increment DECIMAL(10,2) NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,status ENUM('LIVE','CLOSED','UNSOLD') NOT NULL DEFAULT 'LIVE',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(domain_id) REFERENCES domains(id),FOREIGN KEY(seller_id) REFERENCES users(id),INDEX idx_auction_live(status,ends_at)) ENGINE=InnoDB;
CREATE TABLE bids(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,auction_id BIGINT UNSIGNED NOT NULL,bidder_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(10,2) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(auction_id) REFERENCES auctions(id),FOREIGN KEY(bidder_id) REFERENCES users(id),INDEX idx_bid_high(auction_id,amount)) ENGINE=InnoDB;
